//! Journal filesystem layer: <project>/.journal/logs/YYYY-MM-DD.md — one file per
//! day, plain markdown, written by agents directly or generated by the journal
//! writer (core/journal-gen.ts). The filesystem is the truth source; nothing
//! journal-related enters mem0.

import fs from 'node:fs';
import path from 'node:path';

/** Only exact date-named files count — everything else in .journal/logs is ignored. */
export const JOURNAL_FILE_RE = /^\d{4}-\d{2}-\d{2}\.md$/;
/** A misconfigured/huge log file must not ship wholesale to the renderer. */
const MAX_FILE_BYTES = 2 * 1024 * 1024;

export function journalDirOf(projectId: string): string {
  return path.join(projectId, '.journal', 'logs');
}

export interface JournalFile {
  date: string;
  content: string;
  mtime: number;
}

/** Scan <project>/.journal/logs/*.md. Unreadable files are skipped (transient
 *  writes reappear on the next refresh); a missing directory is empty. */
export function listJournalFiles(projectId: string): JournalFile[] {
  const dir = journalDirOf(projectId);
  let entries: fs.Dirent[];
  try {
    entries = fs.readdirSync(dir, { withFileTypes: true });
  } catch {
    return []; // no journals yet
  }
  const out: JournalFile[] = [];
  for (const e of entries) {
    if (!e.isFile() || !JOURNAL_FILE_RE.test(e.name)) continue;
    const file = path.join(dir, e.name);
    try {
      const st = fs.statSync(file);
      if (st.size > MAX_FILE_BYTES) continue;
      out.push({
        date: e.name.slice(0, 10),
        content: fs.readFileSync(file, 'utf-8'),
        mtime: Math.round(st.mtimeMs),
      });
    } catch {
      // transient write — skipped until the next refresh
    }
  }
  return out.sort((a, b) => (a.date < b.date ? 1 : -1));
}

/** Existing journal dates for a project (names only — cheap existence check
 *  for the generator's "already written" filter). */
export function journalDates(projectId: string): Set<string> {
  let names: string[];
  try {
    names = fs.readdirSync(journalDirOf(projectId));
  } catch {
    return new Set();
  }
  return new Set(names.filter((n) => JOURNAL_FILE_RE.test(n)).map((n) => n.slice(0, 10)));
}

/** A `*` .gitignore inside .journal hides the whole directory (itself included)
 *  from git status — .journal is local working data, never committed. */
function ensureJournalGitIgnore(projectId: string): void {
  const dot = path.join(projectId, '.journal', '.gitignore');
  if (fs.existsSync(dot)) return;
  fs.writeFileSync(dot, '*\n', 'utf-8');
}

/** Debug regeneration: delete the project's journal files dated before
 *  `before` (today's file is agent-owned and the writer never touches it).
 *  Returns the deleted dates; an unlink failure just leaves that day to be
 *  skipped by the regeneration pass. */
export function deleteJournalFilesBefore(projectId: string, before: string): string[] {
  const dir = journalDirOf(projectId);
  let entries: fs.Dirent[];
  try {
    entries = fs.readdirSync(dir, { withFileTypes: true });
  } catch {
    return [];
  }
  const deleted: string[] = [];
  for (const e of entries) {
    if (!e.isFile() || !JOURNAL_FILE_RE.test(e.name)) continue;
    if (e.name.slice(0, 10) >= before) continue;
    try {
      fs.unlinkSync(path.join(dir, e.name));
      deleted.push(e.name.slice(0, 10));
    } catch {
      // transient — that day simply won't regenerate this pass
    }
  }
  return deleted;
}

/** Create-if-missing write of one day's journal. Returns false when the file
 *  already exists (the generator never rewrites — agents and users own edits). */
export function writeJournalFile(projectId: string, date: string, content: string): boolean {
  const file = path.join(journalDirOf(projectId), `${date}.md`);
  if (fs.existsSync(file)) return false;
  fs.mkdirSync(path.dirname(file), { recursive: true });
  ensureJournalGitIgnore(projectId);
  fs.writeFileSync(file, content.trimEnd() + '\n', 'utf-8');
  return true;
}
